void main() {
  group('Nahdi parser — raw stream record', () {
    final products = NahdiPriceService.parseProducts(rawRecord);

    test('extracts sku, arabic and english names', () {
      expect(products, isNotEmpty);
      expect(products.first.sku, isNotEmpty);
      expect(products.first.nameAr, isNotEmpty);
    });

    test('extracts price when present', () {
      final priced = products.where((p) => p.priceSar != null).toList();
      expect(priced, isNotEmpty);
      expect(priced.first.priceSar!, greaterThan(0));
    });

    test('extracts usage lines in Arabic', () {
      final withUsage = products.where((p) => p.usageLines.isNotEmpty).toList();
      expect(withUsage, isNotEmpty);
    });

    test('stock flag defaults true when absent', () {
      expect(products.first.inStock, anyOf(isTrue, isFalse));
    });
  });

  group('Nahdi parser — Algolia HTML record', () {
    test('handles highlight markers and value objects', () {
      final products = NahdiPriceService.parseProducts(htmlRecord);
      expect(products, isNotEmpty);
      final p = products.first;
      expect(p.nameAr, isNot(contains('__ais-highlight__')));
      expect(p.nameAr, isNot(contains('__/ais-highlight__')));
    });
  });
}
